import{_ as t,c as a,o as r,ae as i}from"./chunks/framework.DCU7Csu6.js";const h=JSON.parse('{"title":"Tutorials","description":"Step-by-step tutorials for building real-world applications with Wildberries TypeScript SDK","frontmatter":{"title":"Tutorials","description":"Step-by-step tutorials for building real-world applications with Wildberries TypeScript SDK","layout":"doc"},"headers":[],"relativePath":"getting-started/tutorials/index.md","filePath":"getting-started/tutorials/index.md"}'),l={name:"getting-started/tutorials/index.md"};function s(o,e,n,d,u,p){return r(),a("div",null,[...e[0]||(e[0]=[i(`<h1 id="tutorials" tabindex="-1">Tutorials <a class="header-anchor" href="#tutorials" aria-label="Permalink to &quot;Tutorials&quot;">​</a></h1><p>Comprehensive step-by-step tutorials for mastering the Wildberries TypeScript SDK.</p><blockquote><p><strong><a href="./../../ru/getting-started/tutorials/">Русская версия</a></strong> | English Version</p></blockquote><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>These tutorials guide you through building real-world e-commerce solutions with the Wildberries marketplace. Each tutorial includes complete working code examples that you can use as a foundation for your projects.</p><hr><h2 id="available-tutorials" tabindex="-1">Available Tutorials <a class="header-anchor" href="#available-tutorials" aria-label="Permalink to &quot;Available Tutorials&quot;">​</a></h2><h3 id="_1-product-catalog-sync" tabindex="-1">1. Product Catalog Sync <a class="header-anchor" href="#_1-product-catalog-sync" aria-label="Permalink to &quot;1. Product Catalog Sync&quot;">​</a></h3><p><strong><a href="./product-catalog-sync.html">Start Tutorial →</a></strong></p><p>Learn how to synchronize your product catalog with Wildberries marketplace.</p><ul><li>Fetch product categories from Wildberries</li><li>Create new product cards with attributes</li><li>Upload product media (images)</li><li>Update product pricing dynamically</li></ul><p><strong>Estimated Time:</strong> 30 minutes | <strong>Difficulty:</strong> Beginner</p><hr><h3 id="_2-order-fulfillment" tabindex="-1">2. Order Fulfillment <a class="header-anchor" href="#_2-order-fulfillment" aria-label="Permalink to &quot;2. Order Fulfillment&quot;">​</a></h3><p><strong><a href="./order-fulfillment.html">Start Tutorial →</a></strong></p><p>Build a complete order fulfillment workflow for FBS (Fulfillment by Seller) orders.</p><ul><li>Retrieve new orders from Wildberries</li><li>Update order statuses through the fulfillment pipeline</li><li>Generate shipping labels and stickers</li><li>Handle supply creation and management</li></ul><p><strong>Estimated Time:</strong> 45 minutes | <strong>Difficulty:</strong> Intermediate</p><hr><h3 id="_3-analytics-dashboard" tabindex="-1">3. Analytics Dashboard <a class="header-anchor" href="#_3-analytics-dashboard" aria-label="Permalink to &quot;3. Analytics Dashboard&quot;">​</a></h3><p><strong><a href="./analytics-dashboard.html">Start Tutorial →</a></strong></p><p>Create a comprehensive analytics dashboard with sales, inventory, and performance metrics.</p><ul><li>Aggregate sales data and calculate KPIs</li><li>Track inventory levels across warehouses</li><li>Monitor return rates and customer feedback</li><li>Generate reports in various formats</li></ul><p><strong>Estimated Time:</strong> 60 minutes | <strong>Difficulty:</strong> Intermediate</p><hr><h3 id="_4-multi-module-integration" tabindex="-1">4. Multi-Module Integration <a class="header-anchor" href="#_4-multi-module-integration" aria-label="Permalink to &quot;4. Multi-Module Integration&quot;">​</a></h3><p><strong><a href="./multi-module-integration.html">Start Tutorial →</a></strong></p><p>Build an advanced system that integrates multiple SDK modules for complex business workflows.</p><ul><li>Combine Products, Orders, Analytics, and Reports modules</li><li>Implement cross-module data pipelines</li><li>Handle errors and retries across modules</li><li>Build robust automated workflows</li></ul><p><strong>Estimated Time:</strong> 90 minutes | <strong>Difficulty:</strong> Advanced</p><hr><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>Before starting any tutorial, ensure you have:</p><ul><li>✅ <strong>Node.js ≥ 20.0.0</strong> installed</li><li>✅ <strong>Wildberries seller account</strong> with API access</li><li>✅ <strong>SDK installed</strong> via <code>npm install daytona-wildberries-typescript-sdk</code></li><li>✅ <strong>Basic TypeScript knowledge</strong></li><li>✅ Completed the <a href="./../quickstart.html">Quickstart Guide</a></li></ul><hr><h2 id="tutorial-approach" tabindex="-1">Tutorial Approach <a class="header-anchor" href="#tutorial-approach" aria-label="Permalink to &quot;Tutorial Approach&quot;">​</a></h2><p>Each tutorial follows a consistent structure:</p><ol><li><strong>What You&#39;ll Build</strong> - Overview of the end result</li><li><strong>Learning Objectives</strong> - Skills you&#39;ll gain</li><li><strong>Prerequisites</strong> - What you need before starting</li><li><strong>Step-by-Step Instructions</strong> - Detailed implementation guide</li><li><strong>Complete Code</strong> - Full working example</li><li><strong>Next Steps</strong> - Where to go from here</li></ol><hr><h2 id="recommended-learning-path" tabindex="-1">Recommended Learning Path <a class="header-anchor" href="#recommended-learning-path" aria-label="Permalink to &quot;Recommended Learning Path&quot;">​</a></h2><p>For the best learning experience, we recommend completing tutorials in order:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Product Catalog Sync (Beginner)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>2. Order Fulfillment (Intermediate)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>3. Analytics Dashboard (Intermediate)</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>4. Multi-Module Integration (Advanced)</span></span></code></pre></div><p>Each tutorial builds on concepts from previous ones, helping you progressively master the SDK.</p><hr><h2 id="additional-resources" tabindex="-1">Additional Resources <a class="header-anchor" href="#additional-resources" aria-label="Permalink to &quot;Additional Resources&quot;">​</a></h2><ul><li><strong><a href="/daytona-wildberries-typescript-sdk/api/">API Reference</a></strong> - Complete API documentation</li><li><strong><a href="/daytona-wildberries-typescript-sdk/examples/">Examples</a></strong> - Code snippets and use cases</li><li><strong><a href="/daytona-wildberries-typescript-sdk/guides/best-practices.html">Best Practices</a></strong> - SDK usage guidelines</li><li><strong><a href="/daytona-wildberries-typescript-sdk/guides/troubleshooting.html">Troubleshooting</a></strong> - Common issues and solutions</li></ul><hr><h2 id="get-help" tabindex="-1">Get Help <a class="header-anchor" href="#get-help" aria-label="Permalink to &quot;Get Help&quot;">​</a></h2><p>If you encounter issues while working through tutorials:</p><ol><li>Check the <a href="/daytona-wildberries-typescript-sdk/guides/troubleshooting.html">Troubleshooting Guide</a></li><li>Search <a href="https://github.com/salacoste/daytona-wildberries-typescript-sdk/issues" target="_blank" rel="noreferrer">GitHub Issues</a></li><li>Open a new issue with details about your problem</li></ol><hr><p><a href="./../">Back to Getting Started</a> | <a href="./product-catalog-sync.html">Start with Product Catalog Sync →</a></p>`,52)])])}const g=t(l,[["render",s]]);export{h as __pageData,g as default};
